// Section 2: Event Store — append/read via InMemoryEventStore
// ══════════════════════════════════════════════════════════════════════════════

#[tokio::test]
async fn event_store_append_and_read_sequence() {
    let store = InMemoryEventStore::new();
    let id = make_instance_id();

    let events = vec![
        make_envelope(&id, 1),
        make_envelope(&id, 2),
        make_envelope(&id, 3),
    ];

    let final_seq = store.append(&id, events).await.expect("append");
    assert_eq!(final_seq, 3);

    let seq = store.get_sequence(&id).await.expect("get_sequence");
    assert_eq!(seq, 3);
}

#[tokio::test]
async fn event_store_separate_instances_dont_interfere() {
    let store = InMemoryEventStore::new();
    let id1 = InstanceId::from_bytes([0x01; 16]);
    let id2 = InstanceId::from_bytes([0x02; 16]);

    store
        .append(&id1, vec![make_envelope(&id1, 1)])
        .await
        .expect("append id1");
    store
        .append(&id2, vec![make_envelope(&id2, 1), make_envelope(&id2, 2)])
        .await
        .expect("append id2");

    assert_eq!(store.get_sequence(&id1).await.unwrap(), 1);
    assert_eq!(store.get_sequence(&id2).await.unwrap(), 2);
}

#[tokio::test]
async fn event_store_continuation_append() {
    let store = InMemoryEventStore::new();
    let id = make_instance_id();

    store
        .append(&id, vec![make_envelope(&id, 1), make_envelope(&id, 2)])
        .await
        .unwrap();

    store
        .append(&id, vec![make_envelope(&id, 3), make_envelope(&id, 4)])
        .await
        .unwrap();

    assert_eq!(store.get_sequence(&id).await.unwrap(), 4);
}

#[tokio::test]
async fn event_store_rejects_empty_batch() {
    let store = InMemoryEventStore::new();
    let id = make_instance_id();

    let result = store.append(&id, vec![]).await;
    assert!(result.is_err());
}

#[tokio::test]
async fn event_store_rejects_wrong_sequence() {
    let store = InMemoryEventStore::new();
    let id = make_instance_id();

    store
        .append(&id, vec![make_envelope(&id, 1)])
        .await
        .unwrap();

    let result = store.append(&id, vec![make_envelope(&id, 5)]).await;
    assert!(result.is_err());
}

